            0x0E: 0x00,  # OUT_T_H
            0x0F: 0x44,  # WHO_AM_I
            0x20: 0x00,  # CTRL1
            0x21: 0x04,  # CTRL2
            0x23: 0x00,  # CTRL4_INT1_PAD_CTRL
            0x24: 0x00,  # CTRL5_INT2_PAD_CTRL
            0x26: 0x00,  # OUT_T
            0x27: 0x00,  # STATUS
            0x2E: 0x00,  # FIFO_CTRL
            0x2F: 0x00,  # FIFO_SAMPLES
            0x38: 0x00,  # WAKE_UP_SRC
            0x3C: 0x00,  # X_OFS_USR
            0x3D: 0x00,  # Y_OFS_USR
            0x3E: 0x00   # Z_OFS_USR
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr == 0x21 and nbytes == 1:
            return (self.regs[addr] & 0xF0) | 0x0F
        elif addr == 0x38:
            return (self.regs[addr] & 0xC0) | (self.regs[addr] & 0x3F)
        else:
            return self.regs[addr] if addr in self.regs else 0

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr == 0x21 and nbytes == 1:
            self.regs[addr] = (self.regs[addr] & 0x0F) | ((data & 0x0F) << 4)
        elif addr in [0x21, 0x3C, 0x3D, 0x3E]:
            self.regs[addr] = data
        elif addr == 0x38:
            self.regs[addr] = (self.regs[addr] & 0x3F) | ((data & 0x3F) << 6)

